ALTER TABLE tasks ADD CONSTRAINT uq_tasks_id_workspace UNIQUE(id,workspace);
ALTER TABLE budgets ADD CONSTRAINT uq_budgets_id_workspace UNIQUE(id,workspace);
ALTER TABLE external_calls ADD COLUMN workspace varchar;
UPDATE external_calls c SET workspace=t.workspace FROM tasks t WHERE t.id=c.task_id;
ALTER TABLE external_calls ALTER COLUMN workspace SET NOT NULL;
ALTER TABLE external_calls ADD CONSTRAINT uq_calls_id_workspace UNIQUE(id,workspace);
ALTER TABLE external_calls ADD CONSTRAINT fk_call_task_workspace FOREIGN KEY(task_id,workspace) REFERENCES tasks(id,workspace) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE call_reservations ADD COLUMN workspace varchar;
UPDATE call_reservations r SET workspace=b.workspace FROM budgets b WHERE b.id=r.budget_id;
ALTER TABLE call_reservations ALTER COLUMN workspace SET NOT NULL;
ALTER TABLE call_reservations ADD CONSTRAINT uq_reservation_id_workspace UNIQUE(id,workspace);
ALTER TABLE call_reservations ADD CONSTRAINT uq_reservation_id_budget_workspace UNIQUE(id,budget_id,workspace);
ALTER TABLE call_reservations ADD CONSTRAINT fk_reservation_budget_workspace FOREIGN KEY(budget_id,workspace) REFERENCES budgets(id,workspace) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE call_reservations ADD CONSTRAINT fk_reservation_call_workspace FOREIGN KEY(id,workspace) REFERENCES external_calls(id,workspace) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE cost_events ADD COLUMN workspace varchar;
UPDATE cost_events e SET workspace=r.workspace FROM call_reservations r WHERE r.id=e.call_id;
ALTER TABLE cost_events ALTER COLUMN workspace SET NOT NULL;
ALTER TABLE cost_events ADD CONSTRAINT fk_event_reservation_workspace FOREIGN KEY(call_id,workspace) REFERENCES call_reservations(id,workspace) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE billing_receipts ADD CONSTRAINT fk_receipt_reservation_budget_workspace FOREIGN KEY(call_id,budget_id,workspace) REFERENCES call_reservations(id,budget_id,workspace) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX ix_calls_task_workspace ON external_calls(task_id,workspace);
CREATE INDEX ix_reservations_budget_workspace ON call_reservations(budget_id,workspace);
CREATE INDEX ix_events_call_workspace ON cost_events(call_id,workspace);
CREATE INDEX ix_receipts_call_budget_workspace ON billing_receipts(call_id,budget_id,workspace);
ALTER TABLE tasks ADD COLUMN ref_work_id varchar GENERATED ALWAYS AS (NULLIF(payload->>'work_id','')) STORED;
ALTER TABLE tasks ADD COLUMN ref_profile_id varchar GENERATED ALWAYS AS (NULLIF(payload->>'profile_id','')) STORED;
ALTER TABLE tasks ADD CONSTRAINT fk_task_work_workspace FOREIGN KEY(ref_work_id,workspace) REFERENCES records(id,workspace) DEFERRABLE INITIALLY DEFERRED NOT VALID;
ALTER TABLE tasks ADD CONSTRAINT fk_task_profile_workspace FOREIGN KEY(ref_profile_id,workspace) REFERENCES records(id,workspace) DEFERRABLE INITIALLY DEFERRED NOT VALID;
